import React, { useState } from 'react';
import './CSS/Cart.css';

const Cart = () => {
  // Sample cart items matching your product style
  const [cartItems, setCartItems] = useState([
    {
      id: 1,
      title: 'Redmi 17 pro',
      category: 'Electronics',
      price: 49999,
      quantity: 1,
      image: 'Pages/images/Smart phone', // Update with your actual image path
    },
    {
      id: 2,
      title: 'Smart watch',
      category: 'Electronics',
      price: 2099,
      quantity: 2,
      image: '/images/watch.jpg', // Update with your actual image path
    }
  ]);

  const updateQuantity = (id, delta) => {
    setCartItems(prevItems =>
      prevItems.map(item => {
        if (item.id === id) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      })
    );
  };

  const removeItem = (id) => {
    setCartItems(prevItems => prevItems.filter(item => item.id !== id));
  };

  const subtotal = cartItems.reduce((acc, item) => acc + item.price * item.quantity, 0);
  const shipping = subtotal > 0 ? 150 : 0;
  const total = subtotal + shipping;

  return (
    <div className="cart-page">
      <div className="cart-header">
        <h1>Your Shopping Cart</h1>
        <p>Review your selected items before proceeding to secure checkout.</p>
      </div>

      {cartItems.length === 0 ? (
        <div className="empty-cart">
          <p>Your cart is currently empty.</p>
          <a href="/products" className="continue-shopping-btn">Explore Products</a>
        </div>
      ) : (
        <div className="cart-layout">
          {/* Cart Items List */}
          <div className="cart-items-container">
            {cartItems.map(item => (
              <div className="cart-item-card" key={item.id}>
                <div className="cart-item-image">
                  <img src={item.image} alt={item.title} />
                </div>
                <div className="cart-item-details">
                  <span className="cart-item-category">{item.category}</span>
                  <h3>{item.title}</h3>
                  <span className="cart-item-price">₹{item.price}</span>
                </div>
                <div className="cart-item-actions">
                  <div className="quantity-controls">
                    <button onClick={() => updateQuantity(item.id, -1)}>-</button>
                    <span>{item.quantity}</span>
                    <button onClick={() => updateQuantity(item.id, 1)}>+</button>
                  </div>
                  <button className="remove-btn" onClick={() => removeItem(item.id)}>
                    <i className="fa-solid fa-trash"></i> Remove
                  </button>
                </div>
              </div>
            ))}
          </div>

          {/* Cart Summary Card */}
          <div className="cart-summary-card">
            <h2>Order Summary</h2>
            <div className="summary-row">
              <span>Subtotal</span>
              <span>₹{subtotal.toLocaleString()}</span>
            </div>
            <div className="summary-row">
              <span>Estimated Shipping</span>
              <span>₹{shipping}</span>
            </div>
            <hr className="summary-divider" />
            <div className="summary-row total-row">
              <span>Total</span>
              <span>₹{total.toLocaleString()}</span>
            </div>
            <button className="checkout-btn">Proceed to Checkout</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Cart;
